with cleaned as (select *, lower(plan) as plan_lower from subscriptions where start_date > date '2023-04-28'), enriched as (select id, end_date, monthly_fee, status, lag(monthly_fee) over (partition by plan order by end_date asc, id asc) as prev_monthly_fee, row_number() over (partition by plan order by end_date asc, id asc) as row_seq, ntile(5) over (partition by date_trunc('MONTH', end_date), status order by monthly_fee asc, id asc) as monthly_fee_bucket from cleaned), ranked as (select *, row_number() over (partition by status order by end_date desc nulls first, id asc) as rank_in_group from enriched qualify rank_in_group = 1), base as (select *, datediff(current_date(), end_date) as days_since_end_date from ranked where end_date >= date '2023-06-01' and monthly_fee >= 210), cleaned_subscriptions as (select id, end_date, monthly_fee, status, prev_monthly_fee, row_seq, monthly_fee_bucket, rank_in_group, days_since_end_date, least(row_seq, monthly_fee) as least_row_seq_monthly_fee from base where end_date >= to_date('2023-09-15')) select id, end_date, status, row_seq, monthly_fee_bucket, rank_in_group, days_since_end_date, case when status rlike '^(EXPIRED|ACTIVE)$' then 'GROUP_A' when status rlike '^(CANCELLED|PAUSED)$' then 'GROUP_B' else 'CORE' end as status_zone from cleaned_subscriptions order by rank_in_group asc
